class Solution:
    def countHidden(self, text: str, words: List[str]) -> int:
        count = 0
        for w in words:
            i = 0
            for c in text:
                if i < len(w) and c == w[i]:
                    i += 1
            if i == len(w):
                count += 1
        return count

