        int count = 0;
        for (String w : words) {
            int i = 0;
            for (int t = 0; t < text.length() && i < w.length(); t++)
                if (text.charAt(t) == w.charAt(i)) i++;
            if (i == w.length()) count++;
        }
        return count;
    }
}

