import bisect

class Solution:
    def countHidden(self, text: str, words: List[str]) -> int:
        pos = {}
        for i, c in enumerate(text):
            pos.setdefault(c, []).append(i)
        count = 0
        for w in words:
            at, ok = -1, True
            for c in w:
                lst = pos.get(c, [])
                k = bisect.bisect_right(lst, at)
                if k == len(lst):
                    ok = False
                    break
                at = lst[k]
            count += ok
        return count

