class Solution {
    public int countHidden(String text, String[] words) {
        List<List<Integer>> pos = new ArrayList<>();
        for (int c = 0; c < 26; c++) pos.add(new ArrayList<>());
        for (int i = 0; i < text.length(); i++) pos.get(text.charAt(i) - 'a').add(i);
        int count = 0;
        for (String w : words) {
            int at = -1;
            boolean ok = true;
            for (int t = 0; t < w.length() && ok; t++) {
                List<Integer> lst = pos.get(w.charAt(t) - 'a');
                int lo = 0, hi = lst.size();
                while (lo < hi) { int mid = (lo + hi) >>> 1; if (lst.get(mid) <= at) lo = mid + 1; else hi = mid; }
                if (lo == lst.size()) ok = false; else at = lst.get(lo);
            }
            if (ok) count++;
        }
        return count;
    }
}

