int countHidden(char* text, char** words, int wordsSize) {
    int n = strlen(text), start[27] = {0};
    for (int i = 0; i < n; i++) start[text[i] - 'a' + 1]++;
    for (int c = 0; c < 26; c++) start[c + 1] += start[c];
    int* pos = malloc((n + 1) * sizeof(int));
    int fill[26];
    memcpy(fill, start, sizeof fill);
    for (int i = 0; i < n; i++) pos[fill[text[i] - 'a']++] = i;
    int count = 0;
    for (int k = 0; k < wordsSize; k++) {
        int at = -1, ok = 1;
        for (const char* w = words[k]; *w && ok; w++) {
            int lo = start[*w - 'a'], hi = start[*w - 'a' + 1], end = hi;
            while (lo < hi) { int mid = (lo + hi) / 2; if (pos[mid] <= at) lo = mid + 1; else hi = mid; }
            if (lo == end) ok = 0; else at = pos[lo];
        }
        count += ok;
    }
    free(pos);
    return count;
}

