class Solution:
    def countHidden(self, text: str, words: List[str]) -> int:
        waiting = [[] for _ in range(26)]
        for w in words:
            waiting[ord(w[0]) - 97].append((w, 0))
        done = 0
        for c in text:
            k = ord(c) - 97
            bucket, waiting[k] = waiting[k], []
            for w, i in bucket:
                i += 1
                if i == len(w):
                    done += 1
                else:
                    waiting[ord(w[i]) - 97].append((w, i))
        return done

