class Solution {
    public int countHidden(String text, String[] words) {
        int W = words.length;
        int[] head = new int[26], next = new int[W], at = new int[W];
        Arrays.fill(head, -1);
        for (int k = 0; k < W; k++) { int c = words[k].charAt(0) - 'a'; next[k] = head[c]; head[c] = k; }
        int done = 0;
        for (int t = 0; t < text.length(); t++) {
            int c = text.charAt(t) - 'a';
            int k = head[c];
            head[c] = -1;
            while (k != -1) {
                int after = next[k];
                if (++at[k] == words[k].length()) done++;
                else { int d = words[k].charAt(at[k]) - 'a'; next[k] = head[d]; head[d] = k; }
                k = after;
            }
        }
        return done;
    }
}

