class Solution {
public:
    int countHidden(string& text, vector<string>& words) {
        vector<vector<pair<int, int>>> waiting(26);
        for (int k = 0; k < (int) words.size(); k++) waiting[words[k][0] - 'a'].push_back({k, 0});
        int done = 0;
        for (char c : text) {
            vector<pair<int, int>> bucket;
            swap(bucket, waiting[c - 'a']);
            for (auto [k, i] : bucket) {
                i++;
                if (i == (int) words[k].size()) done++;
                else waiting[words[k][i] - 'a'].push_back({k, i});
            }
        }
        return done;
    }
};

