int countHidden(char* text, char** words, int wordsSize) {
    int head[26];
    int* next = malloc((wordsSize + 1) * sizeof(int));
    int* at = calloc(wordsSize + 1, sizeof(int));
    for (int c = 0; c < 26; c++) head[c] = -1;
    for (int k = 0; k < wordsSize; k++) { int c = words[k][0] - 'a'; next[k] = head[c]; head[c] = k; }
    int done = 0;
    for (int t = 0; text[t]; t++) {
        int c = text[t] - 'a';
        int k = head[c];
        head[c] = -1;
        while (k != -1) {
            int after = next[k];
            char want = words[k][++at[k]];
            if (!want) done++;
            else { int d = want - 'a'; next[k] = head[d]; head[d] = k; }
            k = after;
        }
    }
    free(next); free(at);
    return done;
}
